        .init(id: "025", text: "A true hero isn’t measured by the size of his strength, but by the strength of his heart.", movie: "Hercules", year: 1997, source: "https://en.wikiquote.org/wiki/Hercules_(1997_film)"),
        .init(id: "027", text: "Love is putting someone else’s needs before yours.", movie: "Frozen", year: 2013, source: "https://en.wikiquote.org/wiki/Frozen_(2013_film)"),
