        .init(id: "037", text: "One step at a time. One punch at a time. One round at a time.", movie: "Creed", year: 2015, source: "https://en.wikiquote.org/wiki/Creed_(film)"),
        .init(id: "038", text: "You got a dream, you got to protect it.", movie: "The Pursuit of Happyness", year: 2006, source: "https://en.wikiquote.org/wiki/The_Pursuit_of_Happyness"),
        .init(id: "039", text: "Carpe diem. Seize the day, boys. Make your lives extraordinary.", movie: "Dead Poets Society", year: 1989, source: "https://en.wikiquote.org/wiki/Dead_Poets_Society"),
        .init(id: "040", text: "You'll have bad times, but that'll always wake you up to the good stuff you weren't paying attention to.", movie: "Good Will Hunting", year: 1997, source: "https://www.stockq.org/moviescript/G/good-will-hunting.php"),
        .init(id: "041", text: "You have to do the best with what God gave you.", movie: "Forrest Gump", year: 1994, source: "https://en.wikiquote.org/wiki/Forrest_Gump"),
        .init(id: "042", text: "All we have to decide is what to do with the time that is given to us.", movie: "The Lord of the Rings: The Fellowship of the Ring", year: 2001, source: "https://en.wikiquote.org/wiki/The_Lord_of_the_Rings:_The_Fellowship_of_the_Ring"),
        .init(id: "043", text: "There's some good in the world, Mr. Frodo, and it's worth fighting for.", movie: "The Lord of the Rings: The Two Towers", year: 2002, source: "https://en.wikiquote.org/wiki/The_Lord_of_the_Rings:_The_Two_Towers"),
        .init(id: "044", text: "I can’t carry it for you, but I can carry you!", movie: "The Lord of the Rings: The Return of the King", year: 2003, source: "https://en.wikiquote.org/wiki/The_Lord_of_the_Rings:_The_Return_of_the_King"),
        .init(id: "045", text: "It is not our abilities that show us what we truly are. It is our choices.", movie: "Harry Potter and the Chamber of Secrets", year: 2002, source: "https://en.wikiquote.org/wiki/Harry_Potter_and_the_Chamber_of_Secrets_(film)"),
        .init(id: "046", text: "Happiness can be found even in the darkest of times, if one only remembers to turn on the light.", movie: "Harry Potter and the Prisoner of Azkaban", year: 2004, source: "https://en.wikiquote.org/wiki/Harry_Potter_and_the_Prisoner_of_Azkaban_(film)"),
        .init(id: "047", text: "It does not do to dwell on dreams, Harry, and forget to live.", movie: "Harry Potter and the Sorcerer’s Stone", year: 2001, source: "https://clip.cafe/harry-potter-the-sorcerers-stone-2001/it-does-not-do-dwell-on-dreams-s1/"),
        .init(id: "048", text: "Why do we fall?", movie: "Batman Begins", year: 2005, source: "https://en.wikiquote.org/wiki/Batman_Begins"),
        .init(id: "049", text: "A hero can be anyone.", movie: "The Dark Knight Rises", year: 2012, source: "https://en.wikiquote.org/wiki/The_Dark_Knight_Rises"),
        .init(id: "050", text: "With great power comes great responsibility.", movie: "Spider-Man", year: 2002, source: "https://en.wikiquote.org/wiki/Spider-Man_(film)"),
        .init(id: "051", text: "Anyone can wear the mask.", movie: "Spider-Man: Into the Spider-Verse", year: 2018, source: "https://en.wikiquote.org/wiki/Spider-Man:_Into_the_Spider-Verse"),
        .init(id: "052", text: "We have to be steady and give up the thing we want the most.", movie: "Spider-Man 2", year: 2004, source: "https://en.wikiquote.org/wiki/Spider-Man_2"),
        .init(id: "053", text: "I can do this all day.", movie: "Captain America: The First Avenger", year: 2011, source: "https://en.wikiquote.org/wiki/Captain_America:_The_First_Avenger"),
        .init(id: "054", text: "Whatever it takes.", movie: "Avengers: Endgame", year: 2019, source: "https://en.wikiquote.org/wiki/Avengers:_Endgame"),
        .init(id: "055", text: "In times of crisis, the wise build bridges, while the foolish build barriers.", movie: "Black Panther", year: 2018, source: "https://en.wikiquote.org/wiki/Black_Panther_(film)"),
        .init(id: "056", text: "Only love can truly save the world.", movie: "Wonder Woman", year: 2017, source: "https://en.wikiquote.org/wiki/Wonder_Woman_(2017_film)"),
        .init(id: "057", text: "There's a difference between knowing the path and walking the path.", movie: "The Matrix", year: 1999, source: "https://clip.cafe/the-matrix-1999/sooner-later-youll-realize-just-i-did/"),
        .init(id: "058", text: "If you put your mind to it, you could accomplish anything.", movie: "Back to the Future", year: 1985, source: "https://en.wikiquote.org/wiki/Back_to_the_Future"),
        .init(id: "059", text: "Your future is whatever you make it. So make it a good one.", movie: "Back to the Future Part III", year: 1990, source: "https://en.wikiquote.org/wiki/Back_to_the_Future_Part_III"),
        .init(id: "060", text: "We used to look up at the sky and wonder at our place in the stars.", movie: "Interstellar", year: 2014, source: "https://en.wikiquote.org/wiki/Interstellar"),
        .init(id: "061", text: "You just begin.", movie: "The Martian", year: 2015, source: "https://en.wikiquote.org/wiki/The_Martian_(film)"),
        .init(id: "062", text: "Failure is not an option.", movie: "Apollo 13", year: 1995, source: "https://en.wikiquote.org/wiki/Apollo_13_(film)"),
        .init(id: "063", text: "Every time we get a chance to get ahead they move the finish line.", movie: "Hidden Figures", year: 2016, source: "https://en.wikiquote.org/wiki/Hidden_Figures"),
        .init(id: "064", text: "The hard is what makes it great.", movie: "A League of Their Own", year: 1992, source: "https://en.wikiquote.org/wiki/A_League_of_Their_Own"),
        .init(id: "065", text: "Attitude reflects leadership, captain.", movie: "Remember the Titans", year: 2000, source: "https://movie-sounds.org/famous/remember-the-titans/557530"),
        .init(id: "066", text: "The noblest art is that of making others happy.", movie: "The Greatest Showman", year: 2017, source: "https://en.wikiquote.org/wiki/The_Greatest_Showman"),
        .init(id: "067", text: "If we’re kind and polite, the world will be right.", movie: "Paddington 2", year: 2017, source: "https://en.wikiquote.org/wiki/Paddington_2"),
        .init(id: "068", text: "No man is a failure who has friends.", movie: "It’s a Wonderful Life", year: 1946, source: "https://en.wikiquote.org/wiki/It%27s_a_Wonderful_Life"),
        .init(id: "069", text: "Beautiful things don’t ask for attention.", movie: "The Secret Life of Walter Mitty", year: 2013, source: "https://www.imdb.com/title/tt0359950/quotes/"),
        .init(id: "070", text: "Life moves pretty fast. If you don’t stop and look around once in a while, you could miss it.", movie: "Ferris Bueller’s Day Off", year: 1986, source: "https://en.wikiquote.org/wiki/Ferris_Bueller%27s_Day_Off"),
        .init(id: "072", text: "You must believe.", movie: "Kung Fu Panda", year: 2008, source: "https://en.wikiquote.org/wiki/Kung_Fu_Panda"),
        .init(id: "073", text: "Hope is a good thing, maybe the best of things.", movie: "The Shawshank Redemption", year: 1994, source: "https://en.wikiquote.org/wiki/The_Shawshank_Redemption"),
        .init(id: "074", text: "You must unlearn what you have learned.", movie: "The Empire Strikes Back", year: 1980, source: "https://en.wikiquote.org/wiki/Star_Wars_Episode_V:_The_Empire_Strikes_Back"),
        .init(id: "075", text: "The past can hurt.", movie: "The Lion King", year: 1994, source: "https://en.wikiquote.org/wiki/The_Lion_King"),
        .init(id: "076", text: "Not everyone can become a great artist, but a great artist can come from anywhere.", movie: "Ratatouille", year: 2007, source: "https://en.wikiquote.org/wiki/Ratatouille"),
        .init(id: "077", text: "You have more power than you realize.", movie: "The Incredibles", year: 2004, source: "https://en.wikiquote.org/wiki/The_Incredibles"),
        .init(id: "078", text: "Thanks for the adventure – now go have a new one!", movie: "Up", year: 2009, source: "https://en.wikipedia.org/wiki/Up_%282009_film%29"),
        .init(id: "080", text: "You don’t meet a girl like that every dynasty.", movie: "Mulan", year: 1998, source: "https://en.wikiquote.org/wiki/Mulan_(1998_film)"),
        .init(id: "082", text: "Real life is messy.", movie: "Zootopia", year: 2016, source: "https://en.wikiquote.org/wiki/Zootopia"),
        .init(id: "084", text: "From failing, you learn. From success, not so much.", movie: "Meet the Robinsons", year: 2007, source: "https://www.springfieldspringfield.co.uk/movie_script.php?movie=meet-the-robinsons"),
        .init(id: "086", text: "You just need to believe it some more.", movie: "The Lego Movie", year: 2014, source: "https://en.wikiquote.org/wiki/The_Lego_Movie"),
