        .init(id: "090", text: "You ain’t never had a friend like me.", movie: "Aladdin", year: 1992, source: "https://en.wikiquote.org/wiki/Aladdin_(1992_Disney_film)"),
        .init(id: "092", text: "Some people are worth melting for.", movie: "Frozen", year: 2013, source: "https://en.wikiquote.org/wiki/Frozen_(2013_film)"),
        .init(id: "094", text: "As you wish.", movie: "The Princess Bride", year: 1987, source: "https://en.wikiquote.org/wiki/The_Princess_Bride_(film)"),
        .init(id: "095", text: "That’s how winning is done!", movie: "Rocky Balboa", year: 2006, source: "https://en.wikiquote.org/wiki/Rocky_Balboa"),
        .init(id: "096", text: "You want something, go get it. Period.", movie: "The Pursuit of Happyness", year: 2006, source: "https://en.wikiquote.org/wiki/The_Pursuit_of_Happyness"),
        .init(id: "097", text: "Words and ideas can change the world.", movie: "Dead Poets Society", year: 1989, source: "https://en.wikiquote.org/wiki/Dead_Poets_Society"),
        .init(id: "099", text: "I will take the Ring.", movie: "The Lord of the Rings: The Fellowship of the Ring", year: 2001, source: "https://en.wikiquote.org/wiki/The_Lord_of_the_Rings:_The_Fellowship_of_the_Ring"),
        .init(id: "100", text: "This day we fight!", movie: "The Lord of the Rings: The Return of the King", year: 2003, source: "https://en.wikiquote.org/wiki/The_Lord_of_the_Rings:_The_Return_of_the_King"),
