        .init(id: "103", text: "Not a perfect soldier, but a good man.", movie: "Captain America: The First Avenger", year: 2011, source: "https://en.wikiquote.org/wiki/Captain_America:_The_First_Avenger"),
        .init(id: "104", text: "Free your mind.", movie: "The Matrix", year: 1999, source: "https://en.wikiquote.org/wiki/The_Matrix_(film)"),
        .init(id: "105", text: "You solve one problem. And you solve the next one.", movie: "The Martian", year: 2015, source: "https://en.wikiquote.org/wiki/The_Martian_(film)"),
        .init(id: "106", text: "I have nothing to prove to you.", movie: "Captain Marvel", year: 2019, source: "https://en.wikiquote.org/wiki/Captain_Marvel_(film)"),
        .init(id: "107", text: "We're a lot stronger than you say we are...", movie: "A Bug's Life", year: 1998, source: "https://en.wikiquote.org/wiki/A_Bug%27s_Life"),
