        .init(id: "109", text: "May the Force be with you.", movie: "Star Wars Episode IV: A New Hope", year: 1977, source: "https://en.wikiquote.org/wiki/Star_Wars_Episode_IV:_A_New_Hope"),
        .init(id: "110", text: "Fortune favours the brave, dude.", movie: "Pacific Rim", year: 2013, source: "https://en.wikiquote.org/wiki/Pacific_Rim_(film)"),
        .init(id: "111", text: "Honoring your parents sounds great, but if you take it too far, well, you might forget to honor yourself.", movie: "Turning Red", year: 2022, source: "https://en.wikiquote.org/wiki/Turning_Red"),
        .init(id: "112", text: "As long as we're together, it doesn't matter to me.", movie: "Madagascar", year: 2005, source: "https://en.wikiquote.org/wiki/Madagascar_(2005_film)"),
        .init(id: "113", text: "LIFE MADE ME ME!", movie: "Guardians of the Galaxy Vol. 3", year: 2023, source: "https://en.wikiquote.org/wiki/Guardians_of_the_Galaxy_Vol._3"),
        .init(id: "114", text: "With your help I believe I can run even faster.", movie: "Chariots of Fire", year: 1981, source: "https://en.wikiquote.org/wiki/Chariots_of_Fire"),
        .init(id: "115", text: "It's the magic of risking everything for a dream that nobody sees but you.", movie: "Million Dollar Baby", year: 2004, source: "https://en.wikiquote.org/wiki/Million_Dollar_Baby"),
        .init(id: "116", text: "Surfing isn't the most important thing in life.", movie: "Soul Surfer", year: 2011, source: "https://en.wikiquote.org/wiki/Soul_Surfer"),
        .init(id: "117", text: "Help yourself up for once.", movie: "Creed III", year: 2023, source: "https://en.wikiquote.org/wiki/Creed_III"),
        .init(id: "118", text: "You can use anything negative as fuel to push through to the positive!", movie: "Cars 3", year: 2017, source: "https://en.wikiquote.org/wiki/Cars_3"),
        .init(id: "119", text: "The only thing that matters is what you choose to be now.", movie: "Kung Fu Panda 2", year: 2011, source: "https://en.wikiquote.org/wiki/Kung_Fu_Panda_2"),
        .init(id: "120", text: "He's brave, like a cowboy should be, and kind and smart.", movie: "Toy Story 3", year: 2010, source: "https://en.wikiquote.org/wiki/Toy_Story_3"),
        .init(id: "121", text: "The very things that held ya down are gonna carry ya up and up and up!", movie: "Dumbo", year: 1941, source: "https://en.wikiquote.org/wiki/Dumbo"),
        .init(id: "122", text: "You know the jungle, I know humans, and I know that together we can stop them.", movie: "Rio 2", year: 2014, source: "https://en.wikiquote.org/wiki/Rio_2"),
        .init(id: "123", text: "The only thing I do know is that we have to be kind.", movie: "Everything Everywhere All at Once", year: 2022, source: "https://en.wikiquote.org/wiki/Everything_Everywhere_All_at_Once"),
        .init(id: "124", text: "You must write your first draft with your heart.", movie: "Finding Forrester", year: 2000, source: "https://en.wikiquote.org/wiki/Finding_Forrester"),
        .init(id: "125", text: "No matter what you choose, you'll always be my little brother.", movie: "Brother Bear", year: 2003, source: "https://en.wikiquote.org/wiki/Brother_Bear"),
        .init(id: "126", text: "But that's why we gotta stick together!", movie: "Shrek", year: 2001, source: "https://en.wikiquote.org/wiki/Shrek"),
        .init(id: "127", text: "You can look beyond what people want, and what they need, and you can choose for yourself.", movie: "The Devil Wears Prada", year: 2006, source: "https://en.wikiquote.org/wiki/The_Devil_Wears_Prada"),
        .init(id: "128", text: "But you can always change it if you want.", movie: "The Croods", year: 2013, source: "https://en.wikiquote.org/wiki/The_Croods"),
        .init(id: "129", text: "Goonies never say die!", movie: "The Goonies", year: 1985, source: "https://en.wikiquote.org/wiki/The_Goonies"),
        .init(id: "130", text: "As long as we're together, everything is gonna be okay!", movie: "The Super Mario Bros. Movie", year: 2023, source: "https://en.wikiquote.org/wiki/The_Super_Mario_Bros._Movie"),
        .init(id: "131", text: "Believe in me, as I believed in you.", movie: "Spider-Man", year: 2002, source: "https://en.wikiquote.org/wiki/Spider-Man_(film)"),
        .init(id: "132", text: "Whenever someone creates something with all of their heart, then that creation is given a soul.", movie: "The Cat Returns", year: 2002, source: "https://en.wikiquote.org/wiki/The_Cat_Returns"),
        .init(id: "133", text: "If you can't say somethin' nice, don't say nothin' at all.", movie: "Bambi", year: 1942, source: "https://en.wikiquote.org/wiki/Bambi"),
        .init(id: "134", text: "So let's just give this everything we got.", movie: "School of Rock", year: 2003, source: "https://en.wikiquote.org/wiki/School_of_Rock"),
        .init(id: "135", text: "I have to do the best I can with what I have.", movie: "The Dark Knight", year: 2008, source: "https://en.wikiquote.org/wiki/The_Dark_Knight_(film)"),
        .init(id: "136", text: "Man's grasp exceeds his nerve.", movie: "The Prestige", year: 2006, source: "https://en.wikiquote.org/wiki/The_Prestige_(film)"),
        .init(id: "137", text: "Louis, I think this is the beginning of a beautiful friendship.", movie: "Casablanca", year: 1942, source: "https://en.wikiquote.org/wiki/Casablanca"),
        .init(id: "138", text: "You are the true dreamers.", movie: "Stand and Deliver", year: 1988, source: "https://en.wikiquote.org/wiki/Stand_and_Deliver"),
        .init(id: "139", text: "Most great ideas come from hard work and careful planning.", movie: "Matilda", year: 1996, source: "https://en.wikiquote.org/wiki/Matilda"),
        .init(id: "140", text: "An honest man has nothing to fear, so I'm trying my best not to be afraid.", movie: "Catch Me If You Can", year: 2002, source: "https://en.wikiquote.org/wiki/Catch_Me_If_You_Can"),
        .init(id: "141", text: "We instill hope again and again and again.", movie: "Saving Mr. Banks", year: 2013, source: "https://en.wikiquote.org/wiki/Saving_Mr._Banks"),
        .init(id: "142", text: "Pain is the best teacher.", movie: "The Super Mario Bros. Movie", year: 2023, source: "https://en.wikiquote.org/wiki/The_Super_Mario_Bros._Movie"),
        .init(id: "143", text: "We are what they grow beyond.", movie: "Star Wars: The Last Jedi", year: 2017, source: "https://en.wikiquote.org/wiki/Star_Wars:_The_Last_Jedi"),
        .init(id: "144", text: "It's not easy to stand alone against the ridicule of others.", movie: "12 Angry Men", year: 1957, source: "https://en.wikiquote.org/wiki/12_Angry_Men"),
        .init(id: "145", text: "I'll take the dangerous one, because I'm not afraid of a challenge.", movie: "Legally Blonde", year: 2001, source: "https://en.wikiquote.org/wiki/Legally_Blonde"),
        .init(id: "146", text: "All my hard work has paid off.", movie: "How to Train Your Dragon 2", year: 2014, source: "https://en.wikiquote.org/wiki/How_to_Train_Your_Dragon_2"),
        .init(id: "147", text: "A thing isn't beautiful because it lasts.", movie: "Avengers: Age of Ultron", year: 2015, source: "https://en.wikiquote.org/wiki/Avengers:_Age_of_Ultron"),
        .init(id: "148", text: "If there's anything we've learned from this delightful adventure, Kowalski, it's that looks don't matter.", movie: "Penguins of Madagascar", year: 2014, source: "https://en.wikiquote.org/wiki/Penguins_of_Madagascar"),
        .init(id: "149", text: "You must be imaginative, and strong-hearted.", movie: "Ratatouille", year: 2007, source: "https://en.wikiquote.org/wiki/Ratatouille"),
        .init(id: "150", text: "To know yourself, you must face them both.", movie: "Shang-Chi and the Legend of the Ten Rings", year: 2021, source: "https://en.wikiquote.org/wiki/Shang-Chi_and_the_Legend_of_the_Ten_Rings"),
        .init(id: "151", text: "We just need to keep trying!", movie: "Monsters University", year: 2013, source: "https://en.wikiquote.org/wiki/Monsters_University"),
        .init(id: "152", text: "I now understand that you are kind, compassionate, brave, and funny.", movie: "The Peanuts Movie", year: 2015, source: "https://en.wikiquote.org/wiki/The_Peanuts_Movie"),
        .init(id: "153", text: "If you build it, he will come.", movie: "Field of Dreams", year: 1989, source: "https://en.wikiquote.org/wiki/Field_of_Dreams"),
        .init(id: "154", text: "And the best way to learn it is to do it.", movie: "The Sword in the Stone", year: 1963, source: "https://en.wikiquote.org/wiki/The_Sword_in_the_Stone"),
        .init(id: "155", text: "And try very hard not to be predictable.", movie: "Fantastic Beasts and Where to Find Them", year: 2016, source: "https://en.wikiquote.org/wiki/Fantastic_Beasts_and_Where_to_Find_Them"),
        .init(id: "156", text: "One great rock show can change the world.", movie: "School of Rock", year: 2003, source: "https://en.wikiquote.org/wiki/School_of_Rock"),
        .init(id: "157", text: "Do not give into fear!", movie: "The Lord of the Rings: The Return of the King", year: 2003, source: "https://en.wikiquote.org/wiki/The_Lord_of_the_Rings:_The_Return_of_the_King"),
        .init(id: "158", text: "You are going to help create happy memories that will last for the rest of her life.", movie: "Toy Story 4", year: 2019, source: "https://en.wikiquote.org/wiki/Toy_Story_4"),
        .init(id: "159", text: "I will live my life in the past, the present, and the future.", movie: "The Muppet Christmas Carol", year: 1992, source: "https://en.wikiquote.org/wiki/The_Muppet_Christmas_Carol"),
        .init(id: "160", text: "True inspiration is impossible to fake.", movie: "Inception", year: 2010, source: "https://en.wikiquote.org/wiki/Inception_(film)"),
        .init(id: "161", text: "They win by making you think you're alone, remember.", movie: "Star Wars: The Rise of Skywalker", year: 2019, source: "https://en.wikiquote.org/wiki/Star_Wars:_The_Rise_of_Skywalker"),
        .init(id: "162", text: "That kind of commitment and effort deserves and demands your respect.", movie: "Hoosiers", year: 1986, source: "https://en.wikiquote.org/wiki/Hoosiers"),
        .init(id: "163", text: "In time you'll learn to use it as I have.", movie: "Star Wars Episode VI: Return of the Jedi", year: 1983, source: "https://en.wikiquote.org/wiki/Star_Wars_Episode_VI:_Return_of_the_Jedi"),
        .init(id: "164", text: "But sometimes you can't see what you're learning until you come out the other side.", movie: "Wonder Woman 1984", year: 2020, source: "https://en.wikiquote.org/wiki/Wonder_Woman_1984"),
        .init(id: "165", text: "Fight for what matters to you, no matter what.", movie: "The Amazing Spider-Man 2", year: 2014, source: "https://en.wikiquote.org/wiki/The_Amazing_Spider-Man_2"),
        .init(id: "166", text: "They say when you meet the love of your life, time stops.", movie: "Big Fish", year: 2003, source: "https://en.wikiquote.org/wiki/Big_Fish"),
        .init(id: "167", text: "Live your life, Puss in Boots.", movie: "Puss in Boots: The Last Wish", year: 2022, source: "https://en.wikiquote.org/wiki/Puss_in_Boots:_The_Last_Wish"),
        .init(id: "168", text: "If you believe in peace, then let us keep it.", movie: "Avengers: Age of Ultron", year: 2015, source: "https://en.wikiquote.org/wiki/Avengers:_Age_of_Ultron"),
        .init(id: "169", text: "You have to start looking at the world in a new way.", movie: "Tenet", year: 2020, source: "https://en.wikiquote.org/wiki/Tenet_(film)"),
        .init(id: "170", text: "But when all seemed lost, I stared at defeat and found hope.", movie: "Cloudy with a Chance of Meatballs", year: 2009, source: "https://en.wikiquote.org/wiki/Cloudy_with_a_Chance_of_Meatballs"),
        .init(id: "171", text: "I'm not afraid of you.", movie: "Shang-Chi and the Legend of the Ten Rings", year: 2021, source: "https://en.wikiquote.org/wiki/Shang-Chi_and_the_Legend_of_the_Ten_Rings"),
        .init(id: "172", text: "I think we can say we are living the impossible.", movie: "Hidden Figures", year: 2016, source: "https://en.wikiquote.org/wiki/Hidden_Figures"),
        .init(id: "173", text: "A life can be made right.", movie: "The Muppet Christmas Carol", year: 1992, source: "https://en.wikiquote.org/wiki/The_Muppet_Christmas_Carol"),
        .init(id: "174", text: "Remember, it is the courage to continue that counts!", movie: "The Peanuts Movie", year: 2015, source: "https://en.wikiquote.org/wiki/The_Peanuts_Movie"),
        .init(id: "175", text: "And dreams accomplish wonderful things.", movie: "Stand and Deliver", year: 1988, source: "https://en.wikiquote.org/wiki/Stand_and_Deliver"),
        .init(id: "176", text: "The word, my friend, is trust.", movie: "Missing Link", year: 2019, source: "https://en.wikiquote.org/wiki/Missing_Link_(2019_film)"),
        .init(id: "177", text: "None of this works unless we have trust.", movie: "The Maze Runner", year: 2014, source: "https://en.wikiquote.org/wiki/The_Maze_Runner"),
        .init(id: "178", text: "Well, I happened to believe you make your own destiny.", movie: "Forrest Gump", year: 1994, source: "https://en.wikiquote.org/wiki/Forrest_Gump"),
        .init(id: "179", text: "Look inside yourself and recognize that change starts with you.", movie: "Zootopia", year: 2016, source: "https://en.wikiquote.org/wiki/Zootopia"),
        .init(id: "180", text: "And maybe if you open yourself up to it, there’s a possibility.", movie: "Guardians of the Galaxy Vol. 3", year: 2023, source: "https://en.wikiquote.org/wiki/Guardians_of_the_Galaxy_Vol._3"),
        .init(id: "181", text: "Untrained, but stronger than she knows!", movie: "Star Wars: The Force Awakens", year: 2015, source: "https://en.wikiquote.org/wiki/Star_Wars:_The_Force_Awakens"),
        .init(id: "182", text: "I don't know how I'm going to live with myself if I don't stay true to what I believe.", movie: "Hacksaw Ridge", year: 2016, source: "https://en.wikiquote.org/wiki/Hacksaw_Ridge"),
        .init(id: "183", text: "Engineers turn dreams into reality.", movie: "The Wind Rises", year: 2013, source: "https://en.wikiquote.org/wiki/The_Wind_Rises"),
        .init(id: "184", text: "I'm gonna grow up, but I won't stop caring about the people in my life.", movie: "The Lego Movie 2: The Second Part", year: 2019, source: "https://en.wikiquote.org/wiki/The_Lego_Movie_2:_The_Second_Part"),
        .init(id: "185", text: "Even the teeniest of actions can change the future.", movie: "Tomorrowland", year: 2015, source: "https://en.wikiquote.org/wiki/Tomorrowland_(film)"),
        .init(id: "186", text: "As we are liberated from our own fear, our presence automatically liberates others.", movie: "Coach Carter", year: 2005, source: "https://en.wikiquote.org/wiki/Coach_Carter"),
        .init(id: "187", text: "That's where ideas begin.", movie: "Star Trek II: The Wrath of Khan", year: 1982, source: "https://en.wikiquote.org/wiki/Star_Trek_II:_The_Wrath_of_Khan"),
        .init(id: "188", text: "Nothing is real if you don't believe in who you are!", movie: "Rocky III", year: 1982, source: "https://en.wikiquote.org/wiki/Rocky_III"),
        .init(id: "189", text: "But what does matter is who we are now and what we do right now.", movie: "The Maze Runner", year: 2014, source: "https://en.wikiquote.org/wiki/The_Maze_Runner"),
        .init(id: "190", text: "Life doesn't give you seat belts!", movie: "The Lego Batman Movie", year: 2017, source: "https://en.wikiquote.org/wiki/The_Lego_Batman_Movie"),
        .init(id: "191", text: "I know you're doing what you believe in, and that's all any of us can do.", movie: "Captain America: Civil War", year: 2016, source: "https://en.wikiquote.org/wiki/Captain_America:_Civil_War"),
        .init(id: "192", text: "Whatever you choose to do with it, you'll be great.", movie: "Spider-Man: Into the Spider-Verse", year: 2018, source: "https://en.wikiquote.org/wiki/Spider-Man:_Into_the_Spider-Verse"),
        .init(id: "193", text: "My faith's in people, I guess.", movie: "Captain America: Civil War", year: 2016, source: "https://en.wikiquote.org/wiki/Captain_America:_Civil_War"),
        .init(id: "194", text: "You just need to believe in yourself!", movie: "Toy Story 2", year: 1999, source: "https://en.wikiquote.org/wiki/Toy_Story_2"),
        .init(id: "195", text: "Unless someone like you cares a whole awful lot, nothing is going to get better. It's not.", movie: "The Lorax", year: 2012, source: "https://en.wikiquote.org/wiki/The_Lorax"),
        .init(id: "196", text: "Let your dreams take wing.", movie: "The Lion King II: Simba's Pride", year: 1998, source: "https://en.wikiquote.org/wiki/The_Lion_King_II:_Simba%27s_Pride"),
        .init(id: "197", text: "Everything is achievable through technology.", movie: "Iron Man 2", year: 2010, source: "https://en.wikiquote.org/wiki/Iron_Man_2"),
        .init(id: "198", text: "I will not fail.", movie: "Rogue One", year: 2016, source: "https://en.wikiquote.org/wiki/Rogue_One"),
        .init(id: "199", text: "Sometimes change can be good.", movie: "Toy Story 4", year: 2019, source: "https://en.wikiquote.org/wiki/Toy_Story_4"),
        .init(id: "200", text: "There's no greater gift than love.", movie: "How to Train Your Dragon: The Hidden World", year: 2019, source: "https://en.wikiquote.org/wiki/How_to_Train_Your_Dragon:_The_Hidden_World"),
        .init(id: "201", text: "Well, you have to start somewhere.", movie: "Rogue One", year: 2016, source: "https://en.wikiquote.org/wiki/Rogue_One"),
        .init(id: "202", text: "Everybody loses a couple, and you either pack up and go home or keep fighting.", movie: "Seabiscuit", year: 2003, source: "https://en.wikiquote.org/wiki/Seabiscuit"),
        .init(id: "203", text: "Now you can either accept that, or you can get to work.", movie: "The Martian", year: 2015, source: "https://en.wikiquote.org/wiki/The_Martian_(film)"),
        .init(id: "204", text: "There's always a happy ending.", movie: "Bolt", year: 2008, source: "https://en.wikiquote.org/wiki/Bolt"),
        .init(id: "205", text: "Faith is believing in something when common sense tells you not to.", movie: "Miracle on 34th Street", year: 1947, source: "https://en.wikiquote.org/wiki/Miracle_on_34th_Street"),
        .init(id: "206", text: "I think everyone deserves to be happy.", movie: "Trolls", year: 2016, source: "https://en.wikiquote.org/wiki/Trolls_(film)"),
        .init(id: "207", text: "And just like that caterpillar, you're about to get your wings.", movie: "Inside Out 2", year: 2024, source: "https://en.wikiquote.org/wiki/Inside_Out_2"),
        .init(id: "208", text: "It's risky, but it's worth a try.", movie: "Solo: A Star Wars Story", year: 2018, source: "https://en.wikiquote.org/wiki/Solo:_A_Star_Wars_Story"),
        .init(id: "209", text: "Whether in the classroom, or on the battlefield, physical fitness can be the difference between success or failure.", movie: "Spider-Man: Homecoming", year: 2017, source: "https://en.wikiquote.org/wiki/Spider-Man:_Homecoming"),
        .init(id: "210", text: "However, you do get to choose who you hold on to.", movie: "The Girl Who Leapt Through Time", year: 2006, source: "https://en.wikiquote.org/wiki/The_Girl_Who_Leapt_Through_Time"),
        .init(id: "211", text: "Discipline, time, and patience are the three great levelers.", movie: "Spirit: Stallion of the Cimarron", year: 2002, source: "https://en.wikiquote.org/wiki/Spirit:_Stallion_of_the_Cimarron"),
        .init(id: "212", text: "Always believe in yourself.", movie: "The Cat Returns", year: 2002, source: "https://en.wikiquote.org/wiki/The_Cat_Returns"),
        .init(id: "213", text: "And you are not failing.", movie: "Freedom Writers", year: 2007, source: "https://en.wikiquote.org/wiki/Freedom_Writers"),
        .init(id: "214", text: "Don't give up hope.", movie: "Madagascar: Escape 2 Africa", year: 2008, source: "https://en.wikiquote.org/wiki/Madagascar:_Escape_2_Africa"),
        .init(id: "215", text: "Be afraid of not having the chance; you have the chance!", movie: "Cars 3", year: 2017, source: "https://en.wikiquote.org/wiki/Cars_3"),
        .init(id: "216", text: "I say we start with dessert and go backwards.", movie: "Ponyo", year: 2008, source: "https://en.wikiquote.org/wiki/Ponyo"),
        .init(id: "217", text: "Just be careful who you change into.", movie: "Spider-Man", year: 2002, source: "https://en.wikiquote.org/wiki/Spider-Man_(film)"),
        .init(id: "218", text: "Rebellions are built on hope!", movie: "Rogue One", year: 2016, source: "https://en.wikiquote.org/wiki/Rogue_One"),
        .init(id: "219", text: "A wondrous future lies before you.", movie: "Sleeping Beauty", year: 1959, source: "https://en.wikiquote.org/wiki/Sleeping_Beauty"),
        .init(id: "220", text: "Everything is possible, even the impossible.", movie: "Mary Poppins Returns", year: 2018, source: "https://en.wikiquote.org/wiki/Mary_Poppins_Returns"),
        .init(id: "221", text: "Because we have heart.", movie: "The Super Mario Bros. Movie", year: 2023, source: "https://en.wikiquote.org/wiki/The_Super_Mario_Bros._Movie"),
        .init(id: "222", text: "It's kindness and joy and love and all the other intangibles.", movie: "Miracle on 34th Street", year: 1947, source: "https://en.wikiquote.org/wiki/Miracle_on_34th_Street"),
        .init(id: "223", text: "As long as we're together, we'll be alright.", movie: "An American Tail", year: 1986, source: "https://en.wikiquote.org/wiki/An_American_Tail"),
        .init(id: "224", text: "Dare to dream, Miss Woods.", movie: "Legally Blonde", year: 2001, source: "https://en.wikiquote.org/wiki/Legally_Blonde"),
        .init(id: "225", text: "Sometimes, you gotta get through your fear to see the beauty on the other side.", movie: "The Good Dinosaur", year: 2015, source: "https://en.wikiquote.org/wiki/The_Good_Dinosaur"),
        .init(id: "226", text: "I will work, if that's what it takes.", movie: "October Sky", year: 1999, source: "https://en.wikiquote.org/wiki/October_Sky"),
        .init(id: "227", text: "If I am to change this image, I must first change myself.", movie: "Finding Nemo", year: 2003, source: "https://en.wikiquote.org/wiki/Finding_Nemo"),
        .init(id: "228", text: "We have to keep moving!", movie: "The Croods", year: 2013, source: "https://en.wikiquote.org/wiki/The_Croods"),
        .init(id: "229", text: "We are the voice of peace, and bit by bit, we will change this world.", movie: "How to Train Your Dragon 2", year: 2014, source: "https://en.wikiquote.org/wiki/How_to_Train_Your_Dragon_2"),
        .init(id: "230", text: "I don't need easy, I just need possible.", movie: "Soul Surfer", year: 2011, source: "https://en.wikiquote.org/wiki/Soul_Surfer"),
        .init(id: "231", text: "Remember, the journey of a thousand miles begins with the first step.", movie: "The Lion King 1½", year: 2004, source: "https://en.wikiquote.org/wiki/The_Lion_King_1%C2%BD"),
        .init(id: "232", text: "All you need is one happy thought, Peter, just one happy thought and it'll make you fly.", movie: "Hook", year: 1991, source: "https://en.wikiquote.org/wiki/Hook_(film)"),
        .init(id: "233", text: "There's no reason to be afraid.", movie: "Kubo and the Two Strings", year: 2016, source: "https://en.wikiquote.org/wiki/Kubo_and_the_Two_Strings"),
        .init(id: "234", text: "We have something to look forward to.", movie: "Casablanca", year: 1942, source: "https://en.wikiquote.org/wiki/Casablanca"),
        .init(id: "235", text: "They will stumble and fall, laugh and cry, but such is life.", movie: "Hotel Transylvania", year: 2012, source: "https://en.wikiquote.org/wiki/Hotel_Transylvania"),
        .init(id: "236", text: "He'll be there for you, no matter what.", movie: "Toy Story 3", year: 2010, source: "https://en.wikiquote.org/wiki/Toy_Story_3"),
        .init(id: "237", text: "All we can do is our best, and sometimes the best that we can do is to start over.", movie: "Captain America: The Winter Soldier", year: 2014, source: "https://en.wikiquote.org/wiki/Captain_America:_The_Winter_Soldier"),
        .init(id: "238", text: "Habit and routine make my life possible.", movie: "Memento", year: 2000, source: "https://en.wikiquote.org/wiki/Memento_(film)"),
        .init(id: "239", text: "While there is life, there is hope.", movie: "The Theory of Everything", year: 2014, source: "https://en.wikiquote.org/wiki/The_Theory_of_Everything_(2014_film)"),
        .init(id: "240", text: "Out there, in the world, we were really living.", movie: "Madagascar 3: Europe's Most Wanted", year: 2012, source: "https://en.wikiquote.org/wiki/Madagascar_3:_Europe%27s_Most_Wanted"),
        .init(id: "241", text: "Pass on what you have learned.", movie: "Star Wars Episode VI: Return of the Jedi", year: 1983, source: "https://en.wikiquote.org/wiki/Star_Wars_Episode_VI:_Return_of_the_Jedi"),
        .init(id: "242", text: "Follow the light.", movie: "The Croods", year: 2013, source: "https://en.wikiquote.org/wiki/The_Croods"),
        .init(id: "243", text: "The only limits on scientific progress are those imposed by society.", movie: "The Prestige", year: 2006, source: "https://en.wikiquote.org/wiki/The_Prestige_(film)"),
        .init(id: "244", text: "Stand tall, boy, have some respect for yourself.", movie: "Back to the Future", year: 1985, source: "https://en.wikiquote.org/wiki/Back_to_the_Future"),
        .init(id: "245", text: "They have hopes and dreams and the promise of a life with dignity.", movie: "The Prince of Egypt", year: 1998, source: "https://en.wikiquote.org/wiki/The_Prince_of_Egypt"),
        .init(id: "246", text: "Because there's always hope.", movie: "Chitty Chitty Bang Bang", year: 1968, source: "https://en.wikiquote.org/wiki/Chitty_Chitty_Bang_Bang"),
        .init(id: "247", text: "Sometimes, to survive, we must become more than we were programmed to be.", movie: "The Wild Robot", year: 2024, source: "https://en.wikiquote.org/wiki/The_Wild_Robot"),
        .init(id: "248", text: "You're amazing.", movie: "Spider-Man: No Way Home", year: 2021, source: "https://en.wikiquote.org/wiki/Spider-Man:_No_Way_Home"),
        .init(id: "249", text: "The choice is yours.", movie: "Spider-Man: Far From Home", year: 2019, source: "https://en.wikiquote.org/wiki/Spider-Man:_Far_From_Home"),
        .init(id: "250", text: "Our deepest fear is that we are powerful beyond measure.", movie: "Coach Carter", year: 2005, source: "https://en.wikiquote.org/wiki/Coach_Carter"),
        .init(id: "251", text: "In my book, we're gonna be winners!", movie: "Hoosiers", year: 1986, source: "https://en.wikiquote.org/wiki/Hoosiers"),
        .init(id: "252", text: "If you won't run, you can't win.", movie: "Chariots of Fire", year: 1981, source: "https://en.wikiquote.org/wiki/Chariots_of_Fire"),
        .init(id: "253", text: "The best thing we can do is stay together.", movie: "Madagascar: Escape 2 Africa", year: 2008, source: "https://en.wikiquote.org/wiki/Madagascar:_Escape_2_Africa"),
        .init(id: "254", text: "Simple acts of kindness and love.", movie: "The Hobbit: An Unexpected Journey", year: 2012, source: "https://en.wikiquote.org/wiki/The_Hobbit:_An_Unexpected_Journey"),
        .init(id: "255", text: "I'mma do my own thing.", movie: "Spider-Man: Across the Spider-Verse", year: 2023, source: "https://en.wikiquote.org/wiki/Spider-Man:_Across_the_Spider-Verse"),
        .init(id: "256", text: "I'm just trying to be the best I can be.", movie: "Cool Runnings", year: 1993, source: "https://en.wikiquote.org/wiki/Cool_Runnings"),
        .init(id: "257", text: "You mustn't be afraid to dream a little bigger, darling.", movie: "Inception", year: 2010, source: "https://en.wikiquote.org/wiki/Inception_(film)"),
        .init(id: "258", text: "But I've learned that every emotion is good for Riley.", movie: "Inside Out 2", year: 2024, source: "https://en.wikiquote.org/wiki/Inside_Out_2"),
        .init(id: "259", text: "I'm trying to turn you into you.", movie: "Kung Fu Panda 3", year: 2016, source: "https://en.wikiquote.org/wiki/Kung_Fu_Panda_3"),
        .init(id: "260", text: "We've got to have faith in each other.", movie: "It’s a Wonderful Life", year: 1946, source: "https://en.wikiquote.org/wiki/It%27s_a_Wonderful_Life"),
        .init(id: "261", text: "But, just for now, why don't you try on some positivity, eh?", movie: "Trolls", year: 2016, source: "https://en.wikiquote.org/wiki/Trolls_(film)"),
        .init(id: "262", text: "Anything different is good.", movie: "Groundhog Day", year: 1993, source: "https://en.wikiquote.org/wiki/Groundhog_Day"),
        .init(id: "263", text: "Forget everything else, and just say it to me.", movie: "The King's Speech", year: 2010, source: "https://en.wikiquote.org/wiki/The_King%27s_Speech"),
        .init(id: "264", text: "This is America, the place to find hope.", movie: "An American Tail", year: 1986, source: "https://en.wikiquote.org/wiki/An_American_Tail"),
        .init(id: "265", text: "You can still do great things.", movie: "The Incredibles", year: 2004, source: "https://en.wikiquote.org/wiki/The_Incredibles"),
        .init(id: "266", text: "I too have encountered great disappointment, but in my eyes, you'll always be one of the greats.", movie: "Despicable Me", year: 2010, source: "https://en.wikiquote.org/wiki/Despicable_Me"),
        .init(id: "267", text: "Remember, Dragon Warrior, anything is possible when you have inner peace.", movie: "Kung Fu Panda 2", year: 2011, source: "https://en.wikiquote.org/wiki/Kung_Fu_Panda_2"),
        .init(id: "268", text: "We make a great team.", movie: "Ice Age", year: 2002, source: "https://en.wikiquote.org/wiki/Ice_Age"),
        .init(id: "269", text: "I've been ready for this my whole life!", movie: "Rudy", year: 1993, source: "https://en.wikiquote.org/wiki/Rudy"),
        .init(id: "270", text: "Sooner or later, you gotta believe in yourself, too, because that’s what growing up is.", movie: "The Muppets", year: 2011, source: "https://en.wikiquote.org/wiki/The_Muppets_(film)"),
        .init(id: "271", text: "We're a great team, Dad!", movie: "Rio 2", year: 2014, source: "https://en.wikiquote.org/wiki/Rio_2"),
        .init(id: "272", text: "Trust me; I can handle anything.", movie: "Legally Blonde", year: 2001, source: "https://en.wikiquote.org/wiki/Legally_Blonde"),
        .init(id: "273", text: "Today there is not a man nor woman in here that shall stand alone.", movie: "Pacific Rim", year: 2013, source: "https://en.wikiquote.org/wiki/Pacific_Rim_(film)"),
        .init(id: "274", text: "It's always about a choice.", movie: "Creed", year: 2015, source: "https://en.wikiquote.org/wiki/Creed_(film)"),
        .init(id: "275", text: "I have to believe that my actions still have meaning, even if I can't remember them.", movie: "Memento", year: 2000, source: "https://en.wikiquote.org/wiki/Memento_(film)"),
        .init(id: "276", text: "Think you're the only ones who dream of better things?", movie: "The Road to El Dorado", year: 2000, source: "https://en.wikiquote.org/wiki/The_Road_to_El_Dorado"),
        .init(id: "277", text: "I'll believe in you all my life, every day.", movie: "E.T. the Extra-Terrestrial", year: 1982, source: "https://en.wikiquote.org/wiki/E.T._the_Extra-Terrestrial"),
        .init(id: "278", text: "Sometimes all it takes to fall in love is the guts to try.", movie: "The Girl Who Leapt Through Time", year: 2006, source: "https://en.wikiquote.org/wiki/The_Girl_Who_Leapt_Through_Time"),
        .init(id: "279", text: "The hardest choices require the strongest wills.", movie: "Avengers: Infinity War", year: 2018, source: "https://en.wikiquote.org/wiki/Avengers:_Infinity_War"),
        .init(id: "280", text: "However bad life may seem, there is always something you can do, and succeed at.", movie: "The Theory of Everything", year: 2014, source: "https://en.wikiquote.org/wiki/The_Theory_of_Everything_(2014_film)"),
        .init(id: "281", text: "Some of us use courage to guide us.", movie: "Brother Bear", year: 2003, source: "https://en.wikiquote.org/wiki/Brother_Bear"),
        .init(id: "282", text: "Sometimes ya gotta back up to go forward.", movie: "Happy Feet Two", year: 2011, source: "https://en.wikiquote.org/wiki/Happy_Feet_Two"),
        .init(id: "283", text: "Stop letting these insecurities get the best of you.", movie: "How to Train Your Dragon: The Hidden World", year: 2019, source: "https://en.wikiquote.org/wiki/How_to_Train_Your_Dragon:_The_Hidden_World"),
        .init(id: "284", text: "When you only have one life, that's what makes it special.", movie: "Puss in Boots: The Last Wish", year: 2022, source: "https://en.wikiquote.org/wiki/Puss_in_Boots:_The_Last_Wish"),
        .init(id: "285", text: "The belonging you seek is not behind you...it is ahead.", movie: "Star Wars: The Force Awakens", year: 2015, source: "https://en.wikiquote.org/wiki/Star_Wars:_The_Force_Awakens"),
        .init(id: "286", text: "You mustn't be so hard on yourself, Your Majesty.", movie: "The Prince of Egypt", year: 1998, source: "https://en.wikiquote.org/wiki/The_Prince_of_Egypt"),
        .init(id: "287", text: "Pay careful attention to everything you see and hear, no matter how unusual it may seem.", movie: "Kubo and the Two Strings", year: 2016, source: "https://en.wikiquote.org/wiki/Kubo_and_the_Two_Strings"),
        .init(id: "288", text: "The greatest teacher, failure is.", movie: "Star Wars: The Last Jedi", year: 2017, source: "https://en.wikiquote.org/wiki/Star_Wars:_The_Last_Jedi"),
        .init(id: "289", text: "Change the way things are.", movie: "The Lorax", year: 2012, source: "https://en.wikiquote.org/wiki/The_Lorax"),
        .init(id: "290", text: "But until you start believing in yourself, you ain't gonna have a life.", movie: "Rocky Balboa", year: 2006, source: "https://en.wikiquote.org/wiki/Rocky_Balboa"),
        .init(id: "291", text: "Hey, if you find a mate in life, you should be loyal.", movie: "Ice Age", year: 2002, source: "https://en.wikiquote.org/wiki/Ice_Age"),
        .init(id: "292", text: "Don't waste your life, Stark.", movie: "Iron Man", year: 2008, source: "https://en.wikiquote.org/wiki/Iron_Man_(2008_film)"),
        .init(id: "293", text: "It'll mean an awful lot of hard work.", movie: "Billy Elliot", year: 2000, source: "https://en.wikiquote.org/wiki/Billy_Elliot"),
        .init(id: "294", text: "Everything you see exists together in a delicate balance.", movie: "The Lion King", year: 1994, source: "https://en.wikiquote.org/wiki/The_Lion_King"),
        .init(id: "295", text: "Don't lose heart, men.", movie: "Pocahontas", year: 1995, source: "https://en.wikiquote.org/wiki/Pocahontas"),
        .init(id: "296", text: "I have just met you and I love you!", movie: "Up", year: 2009, source: "https://en.wikiquote.org/wiki/Up"),
        .init(id: "297", text: "Do not give up!", movie: "The Peanuts Movie", year: 2015, source: "https://en.wikiquote.org/wiki/The_Peanuts_Movie"),
        .init(id: "298", text: "Darling, forever is a long, long time, and time has a way of changing things.", movie: "The Fox and the Hound", year: 1981, source: "https://en.wikiquote.org/wiki/The_Fox_and_the_Hound"),
        .init(id: "299", text: "Life is wonderful, isn’t it?", movie: "The Wind Rises", year: 2013, source: "https://en.wikiquote.org/wiki/The_Wind_Rises"),
        .init(id: "300", text: "You got the makings of greatness in you, but you gotta take the helm and chart your own course!", movie: "Treasure Planet", year: 2002, source: "https://en.wikiquote.org/wiki/Treasure_Planet"),
        .init(id: "301", text: "I love my life, I think it's a miracle.", movie: "Saving Mr. Banks", year: 2013, source: "https://en.wikiquote.org/wiki/Saving_Mr._Banks"),
        .init(id: "302", text: "Look into your heart, the light and the dark.", movie: "Shang-Chi and the Legend of the Ten Rings", year: 2021, source: "https://en.wikiquote.org/wiki/Shang-Chi_and_the_Legend_of_the_Ten_Rings"),
        .init(id: "303", text: "As long as you believe in yourself.", movie: "Puss in Boots: The Last Wish", year: 2022, source: "https://en.wikiquote.org/wiki/Puss_in_Boots:_The_Last_Wish"),
        .init(id: "304", text: "You can't go down now, it can only be up from here.", movie: "The Sword in the Stone", year: 1963, source: "https://en.wikiquote.org/wiki/The_Sword_in_the_Stone"),
        .init(id: "305", text: "Courage of the heart is very rare.", movie: "The Secret of NIMH", year: 1982, source: "https://en.wikiquote.org/wiki/The_Secret_of_NIMH"),
        .init(id: "306", text: "Sometimes it is the people no one imagines anything of who do the things no one can imagine.", movie: "The Imitation Game", year: 2014, source: "https://en.wikiquote.org/wiki/The_Imitation_Game"),
        .init(id: "307", text: "First learn stand, then learn fly.", movie: "The Karate Kid", year: 1984, source: "https://en.wikiquote.org/wiki/The_Karate_Kid"),
        .init(id: "308", text: "It's everything we've dreamed of!", movie: "Despicable Me", year: 2010, source: "https://en.wikiquote.org/wiki/Despicable_Me"),
        .init(id: "309", text: "Because bees don't care what humans think is impossible.", movie: "Bee Movie", year: 2007, source: "https://en.wikiquote.org/wiki/Bee_Movie"),
        .init(id: "310", text: "They say that the brightest spark burns best when circumstances are at their worst.", movie: "Howl's Moving Castle", year: 2004, source: "https://en.wikiquote.org/wiki/Howl%27s_Moving_Castle"),
        .init(id: "311", text: "Self-respect permeates every aspect of your life.", movie: "Lean on Me", year: 1989, source: "https://en.wikiquote.org/wiki/Lean_on_Me"),
        .init(id: "312", text: "Enjoy life while you can.", movie: "Happy Feet", year: 2006, source: "https://en.wikiquote.org/wiki/Happy_Feet"),
        .init(id: "313", text: "Life is good, but it can be better.", movie: "Wonder Woman 1984", year: 2020, source: "https://en.wikiquote.org/wiki/Wonder_Woman_1984"),
        .init(id: "314", text: "I do it because I love it.", movie: "Chariots of Fire", year: 1981, source: "https://en.wikiquote.org/wiki/Chariots_of_Fire"),
        .init(id: "315", text: "Let go of the fear!", movie: "Creed III", year: 2023, source: "https://en.wikiquote.org/wiki/Creed_III"),
        .init(id: "316", text: "Each man's life touches so many other lives.", movie: "It’s a Wonderful Life", year: 1946, source: "https://en.wikiquote.org/wiki/It%27s_a_Wonderful_Life"),
        .init(id: "317", text: "I guess what I'm trying to say, is that if I can change, and you can change, everybody can change!", movie: "Rocky IV", year: 1985, source: "https://en.wikiquote.org/wiki/Rocky_IV"),
        .init(id: "318", text: "You could make millions of people happy.", movie: "The Muppet Movie", year: 1979, source: "https://en.wikiquote.org/wiki/The_Muppet_Movie"),
        .init(id: "319", text: "You will always be in my heart.", movie: "Spirit: Stallion of the Cimarron", year: 2002, source: "https://en.wikiquote.org/wiki/Spirit:_Stallion_of_the_Cimarron"),
        .init(id: "320", text: "We meet our fate together!", movie: "Lean on Me", year: 1989, source: "https://en.wikiquote.org/wiki/Lean_on_Me"),
        .init(id: "321", text: "It's worth a shot.", movie: "Madagascar 3: Europe's Most Wanted", year: 2012, source: "https://en.wikiquote.org/wiki/Madagascar_3:_Europe%27s_Most_Wanted"),
        .init(id: "322", text: "And when you do, you will change the world.", movie: "Iron Man 2", year: 2010, source: "https://en.wikiquote.org/wiki/Iron_Man_2"),
        .init(id: "323", text: "Ride like the wind, Bullseye!", movie: "Toy Story 2", year: 1999, source: "https://en.wikiquote.org/wiki/Toy_Story_2"),
        .init(id: "324", text: "Since...since when do you need a pedigree to help someone?", movie: "Balto", year: 1995, source: "https://en.wikiquote.org/wiki/Balto"),
        .init(id: "325", text: "Though I've grown old, the bell still rings for me; as it does for all who truly believe.", movie: "The Polar Express", year: 2004, source: "https://en.wikiquote.org/wiki/The_Polar_Express"),
        .init(id: "326", text: "Everybody needs help sometimes, Peter, even Spider-Man.", movie: "Spider-Man 3", year: 2007, source: "https://en.wikiquote.org/wiki/Spider-Man_3"),
        .init(id: "327", text: "I don't want to survive! I want to live!", movie: "WALL-E", year: 2008, source: "https://en.wikiquote.org/wiki/WALL-E"),
        .init(id: "328", text: "I believe we could be Kumandra again, but someone has to take the first step.", movie: "Raya and the Last Dragon", year: 2021, source: "https://en.wikiquote.org/wiki/Raya_and_the_Last_Dragon"),
        .init(id: "329", text: "Look, the point is, stop trying so hard to be something you're not.", movie: "How to Train Your Dragon", year: 2010, source: "https://en.wikiquote.org/wiki/How_to_Train_Your_Dragon_(film)"),
        .init(id: "330", text: "We have to be greater than what we suffer.", movie: "The Amazing Spider-Man 2", year: 2014, source: "https://en.wikiquote.org/wiki/The_Amazing_Spider-Man_2"),
        .init(id: "331", text: "Why not try and make something for a change?", movie: "Lilo & Stitch", year: 2002, source: "https://en.wikiquote.org/wiki/Lilo_%26_Stitch"),
        .init(id: "332", text: "It's the best part of each one of us that anything is possible.", movie: "Apollo 13", year: 1995, source: "https://en.wikiquote.org/wiki/Apollo_13_(film)"),
        .init(id: "333", text: "Dreamers need to stick together.", movie: "Tomorrowland", year: 2015, source: "https://en.wikiquote.org/wiki/Tomorrowland_(film)"),
        .init(id: "334", text: "That is why I loved it, because I did the impossible.", movie: "Madagascar 3: Europe's Most Wanted", year: 2012, source: "https://en.wikiquote.org/wiki/Madagascar_3:_Europe%27s_Most_Wanted"),
        .init(id: "335", text: "You’re old enough to make your own choices.", movie: "Hotel Transylvania", year: 2012, source: "https://en.wikiquote.org/wiki/Hotel_Transylvania"),
        .init(id: "336", text: "I will love you as long as I breathe.", movie: "Dune: Part Two", year: 2024, source: "https://en.wikiquote.org/wiki/Dune:_Part_Two"),
        .init(id: "337", text: "Maybe you'll learn a little something about yourself.", movie: "The Breakfast Club", year: 1985, source: "https://en.wikiquote.org/wiki/The_Breakfast_Club"),
        .init(id: "338", text: "You have to live the life you were born to live.", movie: "The Sound of Music", year: 1965, source: "https://en.wikiquote.org/wiki/The_Sound_of_Music"),
        .init(id: "339", text: "To bring wonder, hope and dreams.", movie: "Rise of the Guardians", year: 2012, source: "https://en.wikiquote.org/wiki/Rise_of_the_Guardians"),
        .init(id: "340", text: "You said it yourself, it could be possible!", movie: "The Road to El Dorado", year: 2000, source: "https://en.wikiquote.org/wiki/The_Road_to_El_Dorado"),
        .init(id: "341", text: "Once a place touches you like this, the wind never blows so cold again.", movie: "Field of Dreams", year: 1989, source: "https://en.wikiquote.org/wiki/Field_of_Dreams"),
        .init(id: "342", text: "From that moment on, I was determined to invent something great.", movie: "Cloudy with a Chance of Meatballs", year: 2009, source: "https://en.wikiquote.org/wiki/Cloudy_with_a_Chance_of_Meatballs"),
        .init(id: "343", text: "Then, the work really begins.", movie: "Oppenheimer", year: 2023, source: "https://en.wikiquote.org/wiki/Oppenheimer_(film)"),
        .init(id: "344", text: "In the meantime, keep your chin up, your back straight, and your heart open.", movie: "Stuart Little 2", year: 2002, source: "https://en.wikiquote.org/wiki/Stuart_Little_2"),
        .init(id: "345", text: "Please, don't let your past determine the future.", movie: "Ant-Man", year: 2015, source: "https://en.wikiquote.org/wiki/Ant-Man"),
        .init(id: "346", text: "I can't spend my whole life running away from a bully.", movie: "The Muppet Movie", year: 1979, source: "https://en.wikiquote.org/wiki/The_Muppet_Movie"),
        .init(id: "347", text: "Let's work the problem, people.", movie: "Apollo 13", year: 1995, source: "https://en.wikiquote.org/wiki/Apollo_13_(film)"),
        .init(id: "348", text: "Those setbacks made us stronger, and set us on the path to a bright future.", movie: "Big Hero 6", year: 2014, source: "https://en.wikiquote.org/wiki/Big_Hero_6"),
        .init(id: "349", text: "And once you got the beat, you can do anything.", movie: "Oliver & Company", year: 1988, source: "https://en.wikiquote.org/wiki/Oliver_%26_Company"),
        .init(id: "350", text: "Confronting fear is the destiny of a Jedi.", movie: "Star Wars: The Rise of Skywalker", year: 2019, source: "https://en.wikiquote.org/wiki/Star_Wars:_The_Rise_of_Skywalker"),
        .init(id: "351", text: "But a hundred years, to a steadfast heart, are but a day.", movie: "Sleeping Beauty", year: 1959, source: "https://en.wikiquote.org/wiki/Sleeping_Beauty"),
        .init(id: "352", text: "Now I'm trying to look inside myself and find out how I did it.", movie: "Kiki's Delivery Service", year: 1989, source: "https://en.wikiquote.org/wiki/Kiki%27s_Delivery_Service"),
        .init(id: "353", text: "As long as one child believes, we will be here to fight fear.", movie: "Rise of the Guardians", year: 2012, source: "https://en.wikiquote.org/wiki/Rise_of_the_Guardians"),
        .init(id: "354", text: "If more people valued home above gold, this world would be a merrier place.", movie: "The Hobbit: The Battle of the Five Armies", year: 2014, source: "https://en.wikiquote.org/wiki/The_Hobbit:_The_Battle_of_the_Five_Armies"),
        .init(id: "355", text: "Balance good, karate good, everything good.", movie: "The Karate Kid", year: 1984, source: "https://en.wikiquote.org/wiki/The_Karate_Kid"),
        .init(id: "356", text: "Live long and prosper!", movie: "Star Trek II: The Wrath of Khan", year: 1982, source: "https://en.wikiquote.org/wiki/Star_Trek_II:_The_Wrath_of_Khan"),
        .init(id: "357", text: "You get a chance to prove that you are the best!", movie: "Monsters University", year: 2013, source: "https://en.wikiquote.org/wiki/Monsters_University"),
        .init(id: "358", text: "Because no matter where you run, you just end up running into yourself.", movie: "Breakfast at Tiffany's", year: 1961, source: "https://en.wikiquote.org/wiki/Breakfast_at_Tiffany%27s_(film)"),
        .init(id: "359", text: "We all just have different talents, that's all.", movie: "Elf", year: 2003, source: "https://en.wikiquote.org/wiki/Elf"),
        .init(id: "360", text: "Someday, I will be a beautiful butterfly, and then everything will be better.", movie: "A Bug's Life", year: 1998, source: "https://en.wikiquote.org/wiki/A_Bug%27s_Life"),
        .init(id: "361", text: "True courage is about knowing not when to take a life, but when to spare one.", movie: "The Hobbit: An Unexpected Journey", year: 2012, source: "https://en.wikiquote.org/wiki/The_Hobbit:_An_Unexpected_Journey"),
        .init(id: "362", text: "You’re in control of your own life, remember?", movie: "The Matrix", year: 1999, source: "https://en.wikiquote.org/wiki/The_Matrix_(film)"),
        .init(id: "363", text: "Having power isn't nearly as important as what you choose to do with it.", movie: "Matilda", year: 1996, source: "https://en.wikiquote.org/wiki/Matilda"),
        .init(id: "364", text: "You can't keep me from learning, you can't keep me from studying.", movie: "Patch Adams", year: 1998, source: "https://en.wikiquote.org/wiki/Patch_Adams_(film)"),
        .init(id: "365", text: "A man sees things differently at different times in his life.", movie: "Big Fish", year: 2003, source: "https://en.wikiquote.org/wiki/Big_Fish"),
        .init(id: "366", text: "I feel like everything's going to work out fine.", movie: "Thor: Ragnarok", year: 2017, source: "https://en.wikiquote.org/wiki/Thor:_Ragnarok"),
        .init(id: "367", text: "I promised that I would do this, and I think that I must try.", movie: "The Hobbit: The Desolation of Smaug", year: 2013, source: "https://en.wikiquote.org/wiki/The_Hobbit:_The_Desolation_of_Smaug"),
        .init(id: "368", text: "Then you must fight for what you believe in; guts, stamina, faith.", movie: "Sing 2", year: 2021, source: "https://en.wikiquote.org/wiki/Sing_2"),
        .init(id: "369", text: "Friends stick together to the end.", movie: "The Lion King 1½", year: 2004, source: "https://en.wikiquote.org/wiki/The_Lion_King_1%C2%BD"),
        .init(id: "370", text: "You mustn't give up.", movie: "Princess Mononoke", year: 1997, source: "https://en.wikiquote.org/wiki/Princess_Mononoke"),
        .init(id: "371", text: "Airplanes are beautiful dreams.", movie: "The Wind Rises", year: 2013, source: "https://en.wikiquote.org/wiki/The_Wind_Rises"),
        .init(id: "372", text: "Perhaps it is good to have a beautiful mind, but an even greater gift is to discover a beautiful heart.", movie: "A Beautiful Mind", year: 2001, source: "https://en.wikiquote.org/wiki/A_Beautiful_Mind_(film)"),
        .init(id: "373", text: "And you did the best that anybody could do.", movie: "E.T. the Extra-Terrestrial", year: 1982, source: "https://en.wikiquote.org/wiki/E.T._the_Extra-Terrestrial"),
        .init(id: "374", text: "Yet we know that winter is just another step in the cycle of life.", movie: "Groundhog Day", year: 1993, source: "https://en.wikiquote.org/wiki/Groundhog_Day"),
        .init(id: "375", text: "No thinking - that comes later.", movie: "Finding Forrester", year: 2000, source: "https://en.wikiquote.org/wiki/Finding_Forrester"),
        .init(id: "376", text: "It's what you do that counts.", movie: "Penguins of Madagascar", year: 2014, source: "https://en.wikiquote.org/wiki/Penguins_of_Madagascar"),
        .init(id: "377", text: "In this lifetime, you don't have to prove nothin' to nobody - except yourself.", movie: "Rudy", year: 1993, source: "https://en.wikiquote.org/wiki/Rudy"),
        .init(id: "378", text: "I don't believe in a no-win scenario.", movie: "Star Trek II: The Wrath of Khan", year: 1982, source: "https://en.wikiquote.org/wiki/Star_Trek_II:_The_Wrath_of_Khan"),
    ]
}
